/* Generated by flags-2-env from .cli-flags.toml. Do not edit. */

export interface McpEnvValues {
  readonly act_mcp_flags_config?: string;
  readonly allowed_hosts: string;
  readonly allowed_origins: string;
  readonly log_filter: string;
  readonly otel_exporter_otlp_endpoint?: string;
  readonly otel_service_name?: string;
  readonly port: number;
  readonly server_auth_secret?: string;
}

/** Pure: resolve values from an explicit lookup. */
export function loadFrom(lookup: (key: string) => string | undefined): McpEnvValues {
  return {
    act_mcp_flags_config: nonEmpty(lookup("ACT_MCP_FLAGS_CONFIG")),
    allowed_hosts: nonEmpty(lookup("MCP_ALLOWED_HOSTS")) ?? "localhost,localhost:8080,127.0.0.1,127.0.0.1:8080,[::1],[::1]:8080,act-mcp-server,act-mcp-server:8080",
    allowed_origins: nonEmpty(lookup("MCP_ALLOWED_ORIGINS")) ?? "",
    log_filter: nonEmpty(lookup("RUST_LOG")) ?? "info,act_mcp_server=debug",
    otel_exporter_otlp_endpoint: nonEmpty(lookup("OTEL_EXPORTER_OTLP_ENDPOINT")),
    otel_service_name: nonEmpty(lookup("OTEL_SERVICE_NAME")),
    port: parseIntValue(lookup("PORT"), 8080),
    server_auth_secret: nonEmpty(lookup("SERVER_AUTH_SECRET")),
  };
}

/** Effectful: read the process environment. */
export function loadFromOs(
  env: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): McpEnvValues {
  return loadFrom((key) => env[key]);
}

function nonEmpty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

function parseBool(raw: string | undefined, fallback: boolean): boolean {
  switch (raw?.trim()) {
    case "1":
    case "true":
    case "TRUE":
    case "yes":
    case "YES":
      return true;
    case "0":
    case "false":
    case "FALSE":
    case "no":
    case "NO":
      return false;
    default:
      return fallback;
  }
}

function parseIntValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseInt(raw?.trim() ?? "", 10);
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseFloatValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseFloat(raw?.trim() ?? "");
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseOptionalNumber(raw: string | undefined, asInt: boolean): number | undefined {
  const value = raw?.trim();
  if (!value) {
    return undefined;
  }
  const parsed = asInt ? Number.parseInt(value, 10) : Number.parseFloat(value);
  return Number.isNaN(parsed) ? undefined : parsed;
}

function nonempty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

export function requireEnv(
  name: string,
  expectedType: string,
  examples: readonly string[],
  value: string | undefined,
): string {
  const trimmed = nonempty(value);
  if (trimmed) {
    return trimmed;
  }
  throw new MissingEnvError({ name, expectedType, examples });
}

function pick(
  keys: readonly string[],
  order: readonly string[],
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined>,
  fallback: string | undefined,
): string | undefined {
  for (const source of order) {
    const map = source === "flags" ? flags : source === "env_file" ? dotenv : shell;
    for (const key of keys) {
      const value = nonempty(map[key]);
      if (value !== undefined) {
        return value;
      }
    }
  }
  return nonempty(fallback);
}

function unquote(value: string): string {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith("\"") && trimmed.endsWith("\"")) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }
  return trimmed;
}

export function parseDotenv(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) {
      continue;
    }
    const body = line.startsWith("export ") ? line.slice("export ".length).trim() : line;
    const eq = body.indexOf("=");
    if (eq <= 0) {
      continue;
    }
    const key = body.slice(0, eq).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
      continue;
    }
    out[key] = unquote(body.slice(eq + 1));
  }
  return out;
}

function dotenvEnabled(): boolean {
  const value = typeof process !== "undefined" ? process.env.FLAGS2ENV_DOTENV : undefined;
  return !["0", "false", "FALSE", "no", "NO"].includes(value?.trim() ?? "");
}

export function loadDotenvFiles(files: readonly string[]): Record<string, string> {
  if (!dotenvEnabled() || typeof process === "undefined") {
    return {};
  }
  let fs: { readFileSync: (path: string, encoding: string) => string } | undefined;
  try {
    fs = require("fs") as { readFileSync: (path: string, encoding: string) => string };
  } catch {
    return {};
  }
  return files.reduce<Record<string, string>>((acc, path) => {
    try {
      return { ...acc, ...parseDotenv(fs!.readFileSync(path, "utf8")) };
    } catch {
      return acc;
    }
  }, {});
}
export interface MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
}

export class MissingEnvError extends Error implements MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
  constructor(fields: MissingEnv) {
    super(`missing required environment variable ${fields.name}\n  expected type: ${fields.expectedType}\n  examples: ${fields.examples.join(", ")}`);
    this.name = fields.name;
    this.expectedType = fields.expectedType;
    this.examples = fields.examples;
  }
}

/** Resolve env-key -> value. Empty values fall through to the next source. */
export function loadEnvMap(
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined> = {},
): Record<string, string> {
  const out: Record<string, string> = {};
  const act_mcp_flags_config = pick(["ACT_MCP_FLAGS_CONFIG"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (act_mcp_flags_config !== undefined) out["ACT_MCP_FLAGS_CONFIG"] = act_mcp_flags_config;
  const allowed_hosts = pick(["MCP_ALLOWED_HOSTS"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "localhost,localhost:8080,127.0.0.1,127.0.0.1:8080,[::1],[::1]:8080,act-mcp-server,act-mcp-server:8080");
  if (allowed_hosts !== undefined) out["MCP_ALLOWED_HOSTS"] = allowed_hosts;
  const allowed_origins = pick(["MCP_ALLOWED_ORIGINS"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "");
  if (allowed_origins !== undefined) out["MCP_ALLOWED_ORIGINS"] = allowed_origins;
  const log_filter = pick(["RUST_LOG"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "info,act_mcp_server=debug");
  if (log_filter !== undefined) out["RUST_LOG"] = log_filter;
  const otel_exporter_otlp_endpoint = pick(["OTEL_EXPORTER_OTLP_ENDPOINT"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (otel_exporter_otlp_endpoint !== undefined) out["OTEL_EXPORTER_OTLP_ENDPOINT"] = otel_exporter_otlp_endpoint;
  const otel_service_name = pick(["OTEL_SERVICE_NAME"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (otel_service_name !== undefined) out["OTEL_SERVICE_NAME"] = otel_service_name;
  const port = pick(["PORT"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "8080");
  if (port !== undefined) out["PORT"] = port;
  const server_auth_secret = pick(["SERVER_AUTH_SECRET"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (server_auth_secret !== undefined) out["SERVER_AUTH_SECRET"] = server_auth_secret;
  return out;
}

const DOTENV_FILES: readonly string[] = [".env"];
/** Effectful overlay: `.env` files then `process.env`, ranked per key. */
export function loadEnvMapFromOs(
  shell: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): Record<string, string> {
  return loadEnvMap(shell, loadDotenvFiles(DOTENV_FILES), {});
}
